+    public void cleanExpiredFile(long expireTimestamp) {
+        Set<Long> needToDeleteSet = new HashSet<>();
+        try {
+            metadataStore.iterateFileSegment(fileType, messageQueue.getTopic(), messageQueue.getQueueId(),
