+        // 11 STORETIMESTAMP
+        buffer.putLong(11);
+        // 12 STOREHOSTADDRESS
+        buffer.putLong(10);
+        // 13 RECONSUMETIMES
+        buffer.putInt(13);
+        // 14 Prepared Transaction Offset
+        buffer.putLong(14);
+        // 15 BODY
+        buffer.putInt(0);
