+    }
+
+    public static boolean isSystemTopic(final String topic) {
+        if (StringUtils.isBlank(topic)) {
+            return false;
+        }
+
+        if (SYSTEM_TOPIC_WHITE_LIST.contains(topic)) {
+            return false;
+        }
+
+        if (SYSTEM_TOPIC_LIST.contains(topic)) {
+            return true;
